using Clock=std::chrono::steady_clock;
volatile std::uint64_t sink;
template<class T> inline void opaque(T& v) { asm volatile("" : : "g"(&v) : "memory"); }
template<class T> [[gnu::noinline]] std::uint64_t op_touch(T& t,std::size_t) { opaque(t);auto n=t.size()+t.empty();opaque(t);return n; }
template<class T> [[gnu::noinline]] std::uint64_t op_enum(T& t,std::size_t) { opaque(t);auto v=t.enumerate();opaque(v);return v.size()+t.empty(); }
template<class T> [[gnu::noinline]] std::uint64_t op_each(T& t,std::size_t) { opaque(t);std::uint64_t sum=0;t.for_each([&](auto k,auto v){sum+=k+v+1;});opaque(t);return sum+t.empty(); }
template<class T> [[gnu::noinline]] std::uint64_t op_clear(T& t,std::size_t) { opaque(t);t.clear();opaque(t);return t.size()+t.empty(); }
template<class T> [[gnu::noinline]] std::uint64_t op_reserve(T& t,std::size_t n) { opaque(t);t.reserve(n);opaque(t);return t.size()+t.empty(); }
template<class T> [[gnu::noinline]] std::uint64_t op_clear_reserve(T& t,std::size_t n) { opaque(t);t.clear();t.reserve(n);opaque(t);return t.size()+t.empty(); }
