template<bool Packed> void run(std::size_t n){
 using T=reinsirk::detail::InternalHashMap<std::uint64_t,std::uint64_t,Packed,5>;
 for(bool cycled:{false,true}){
  T t;setup(t,n,cycled);
  const int reps=n>=1000000?64:500000;
  const std::pair<std::string_view,std::uint64_t(*)(T&,std::size_t)> ops[]={{"harness",op_touch<T>},{"enumerate",op_enum<T>},{"for_each",op_each<T>},{"clear",op_clear<T>},{"reserve_no_growth",op_reserve<T>},{"clear_then_reserve_no_growth",op_clear_reserve<T>}};
  for(auto[name,f]:ops){auto start=Clock::now();std::uint64_t sum=0;for(int i=0;i<reps;++i)sum+=f(t,n);auto elapsed=std::chrono::duration<double,std::nano>(Clock::now()-start).count();sink=sum;assert(sum==std::uint64_t(reps));std::cout<<Packed<<':'<<n<<':'<<cycled<<':'<<name<<' '<<elapsed/reps<<' '<<sum<<'\n';}
 }
 // clear後に容量を拡大するreserveのみを計時し、準備と破棄は含めない。
 const int reps=n>=1000000?3:20000;double elapsed=0;std::uint64_t sum=0;
 for(int i=0;i<reps;++i){T t;setup(t,n,true);auto begin=Clock::now();sum+=op_reserve(t,n?n*2:8);elapsed+=std::chrono::duration<double,std::nano>(Clock::now()-begin).count();assert(t.empty());}
 sink=sum;assert(sum==std::uint64_t(reps));std::cout<<Packed<<':'<<n<<":1:reserve_growth "<<elapsed/reps<<' '<<sum<<'\n';
}
